// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(bytes4 probeId) public {
        // The rule is universal over all fuzzed inputs: independently of any probe id,
        // C must still report support for the ERC-165 interface id itself, because
        // ERC1155.supportsInterface falls back to ERC165.supportsInterface, which
        // returns true for type(IERC165).interfaceId (0x01ffc9a7). The mutant drops
        // that super fallback, so it returns false for the ERC-165 id.
        assertTrue(
            c.supportsInterface(type(IERC165).interfaceId),
            "ERC-165 id must be supported via the ERC165 super fallback"
        );
    }
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}
